"""ImmutableR9 fixes OEM481 radio ICopmode binding, keeping coreabstractAPI."""
import argparse,difflib,hashlib,json,shutil
from pathlib import Path
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 p=argparse.ArgumentParser();p.add_argument('--parent',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();assert not a.output.exists();proof=json.loads((a.parent/'result.json').read_text());a.output.mkdir(parents=True);shutil.copytree(a.parent/'source',a.output/'source');shutil.copytree(a.parent/'headers',a.output/'headers');rel='source/wlan/openmitrastar_vopt481_kernel.inc';f=a.output/rel;old=f.read_text();assert old.count('om_vopt_set(&ic->om_vopt,vap->iv_opmode,')==1;assert old.count('om_vopt_get(&ic->om_vopt,vap->iv_opmode,')==1;new=old.replace('om_vopt_set(&ic->om_vopt,vap->iv_opmode,','om_vopt_set(&ic->om_vopt,ic->ic_opmode,',1).replace('om_vopt_get(&ic->om_vopt,vap->iv_opmode,','om_vopt_get(&ic->om_vopt,ic->ic_opmode,',1);f.write_text(new,newline='\n');patch=''.join(difflib.unified_diff(old.splitlines(True),new.splitlines(True),fromfile='a/'+rel,tofile='b/'+rel));(a.output/'vopt34-r9-radio-mode.patch').write_text(patch,newline='\n');shutil.copyfile(a.parent/'vopt34-linux.patch',a.output/'vopt34-parent-r8.patch');proof['files']={str(x.relative_to(a.output)):sha(x)for t in('source','headers')for x in(a.output/t).rglob('*')if x.is_file()};proof['changed_sources']=dict(proof['changed_sources']);proof['changed_sources'][rel]=sha(f);proof.update(status='SOURCE_ONLY_VOPT34_R9_RADIO_OPMODE_BINDING_PENDING_GATES',derived_parent=str(a.parent.resolve()),derived_parent_sha256=sha(a.parent/'result.json'),patch_sha256=sha(a.output/'vopt34-r9-radio-mode.patch'),patch_scope='EXACT_R8_TO_R9_IC_OPMODE_481_ONLY',correction='OEMWEXT481 uses radioICopmode, not perVAPopmode; namedportfieldavoidsrawoffset.');(a.output/'result.json').write_text(json.dumps(proof,indent=2)+'\n');print(json.dumps({'status':proof['status'],'adapter_sha256':sha(f),'patch_sha256':proof['patch_sha256']},indent=2))
if __name__=='__main__':main()
